fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let n = s.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        // Collect the first i+1 characters as a prefix
        let prefix = s[..=i].to_vec();
        result.push(prefix);
    }

    result
}